const emptyState = (icon, msg) =>
  `<div class="m5t-empty"><span class="material-symbols-outlined" aria-hidden="true">${icon}</span><p>${msg}</p></div>`;

const alertHTML = (msg, kind = '') =>
  `<div class="intg-alert ${kind}"><span class="material-symbols-outlined" aria-hidden="true">${kind === 'error' ? 'error' : 'info'}</span><span>${msg}</span></div>`;

export function render() {
  ensureStyles();
  ensurePortfolioStyles();
  if (inPortfolio()) {
    return pickerPageHTML({
      section: 'settings-integrations', title: 'Integrations',
      description: 'Pick a client to manage their connections.',
    });
  }
  return `
    <div class="page-shell" data-section="settings-integrations">
      <div class="page-header">
        <div class="page-header-text">
          <h1 class="page-title">Integrations</h1>
          <p class="page-description">Connected accounts for this workspace.</p>
        </div>
      </div>
      <div id="intg-body">
        <div class="dashboard-card intg-card"><div class="card-body">${emptyState('hourglass_empty', 'Loading…')}</div></div>
      </div>
    </div>`;
}

export async function init() {
  if (inPortfolio()) {
    const fmtN = (n) => Number(n || 0).toLocaleString();
    return initPicker(apiBase(), [
      { h: 'Magnets', td: (r) => `${fmtN(r.magnets.active)}<span style="color:var(--color-text-subtle,#6C7C9A)">/${fmtN(r.magnets.total)}</span>` },
      { h: 'Leads · wk', td: (r) => fmtN(r.leads.this_week) },
    ], { emptyMsg: 'No client orgs yet. Create one under Clients first.' });
  }
  consumeReturnParams();
  await load();
}

/** OAuth outcome rides the search string (survives the hash router). */
function consumeReturnParams() {
  try {
    const sp = new URLSearchParams(window.location.search);
    const providerName = sp.get('provider') === 'calendly' ? 'Calendly' : 'Google Ads';
    if (sp.get('connected') === 'google_ads') { toast('Google Ads connected.', 'success'); state.autoOpenPicker = true; }
    else if (sp.get('connected') === 'calendly') toast('Calendly connected.', 'success');
    else if (sp.get('error')) toast(`${providerName} connection failed (${sp.get('error')}).`, 'error');
    else return;
    window.history.replaceState(null, '', window.location.pathname + window.location.hash);
  } catch { /* cosmetic only */ }
}

async function load() {
  const body = document.getElementById('intg-body');
  try {
    const res = await fetch(`${apiBase()}/m5t/v5/integrations`);
    if (res.status === 403) {
      state.denied = true;
      if (body) body.innerHTML = `<div class="dashboard-card intg-card"><div class="card-body">${emptyState('lock', 'Integrations are managed by workspace admins.')}</div></div>`;
      return;
    }
    const data = await res.json();
    if (!data.ok) throw new Error(data.error || 'load failed');
    state.providers = data.data.providers;
    state.configured = data.data.configured;
    renderBody();
  } catch (e) {
    if (body) body.innerHTML = `<div class="dashboard-card intg-card"><div class="card-body">${emptyState('error', 'Could not load integrations.')}</div></div>`;
  }
}

function googleCard() {
  const org = orgGuid();
  const conns = state.providers?.google_ads || [];
  const conn = conns.find((c) => c.owner_guid === org) || conns[0] || null;
  const configured = !!state.configured?.google_ads;

  let pill = `<span class="intg-state">Not connected</span>`;
  let desc = 'Connect a Google account with access to your ad accounts. Spend lines up against your magnet leads in Ad performance.';
  let actions = '';

  if (!configured) {
    pill = `<span class="intg-state">Not available yet</span>`;
    desc = 'Google Ads reporting is being set up for this platform.';
  } else if (!conn) {
    actions = `<button type="button" class="intg-btn primary" id="intg-g-connect"><span class="material-symbols-outlined" aria-hidden="true">link</span>Connect</button>`;
  } else {
    const n = conn.external_account?.customer_ids?.length || 0;
    const healthy = conn.connect_status === 'ACTIVE';
    if (healthy) {
      pill = `<span class="intg-state on"><span class="material-symbols-outlined" aria-hidden="true">check</span>Connected</span>`;
      desc = n
        ? `This connection can reach <b>${n}</b> ad account${n === 1 ? '' : 's'}. Choose which ones feed reporting; metrics refresh daily in Ad performance.`
        : 'Connected, but no ad accounts are reachable from this Google account. Reconnect with an account that has Google Ads access.';
      actions = `
        <button type="button" class="intg-btn" id="intg-g-accounts"><span class="material-symbols-outlined" aria-hidden="true">checklist</span>Choose accounts</button>
        <button type="button" class="intg-btn" id="intg-g-sync"><span class="material-symbols-outlined" aria-hidden="true">sync</span>Sync now</button>
        <button type="button" class="intg-btn danger" id="intg-g-disconnect"><span class="material-symbols-outlined" aria-hidden="true">link_off</span>Disconnect</button>`;
    } else {
      pill = `<span class="intg-state warn"><span class="material-symbols-outlined" aria-hidden="true">priority_high</span>${esc(conn.connect_status === 'NEEDS_REAUTH' ? 'Reconnect needed' : 'Connection error')}</span>`;
      desc = 'The connection stopped working. Reconnect to resume daily metric refreshes.';
      actions = `
        <button type="button" class="intg-btn primary" id="intg-g-connect"><span class="material-symbols-outlined" aria-hidden="true">link</span>Reconnect</button>
        <button type="button" class="intg-btn danger" id="intg-g-disconnect"><span class="material-symbols-outlined" aria-hidden="true">link_off</span>Disconnect</button>`;
    }
  }

  return `
    <div class="dashboard-card intg-card">
      <div class="card-body">
        <div class="intg-head">
          <span class="intg-mark"><span class="material-symbols-outlined" aria-hidden="true">ads_click</span></span>
          <div class="intg-title-wrap">
            <div class="intg-name-row"><span class="intg-name">Google Ads</span>${pill}</div>
            <div class="intg-sub">Spend and clicks beside your leads.</div>
          </div>
          <div class="intg-actions">${actions}</div>
        </div>
        <p class="intg-desc">${desc}</p>
        <div id="intg-g-picker" style="display:none"></div>
      </div>
    </div>`;
}

