function renderBody() {
  const body = document.getElementById('intg-body');
  if (!body) return;
  body.innerHTML = googleCard() + calendlyCard() + callrailCard();

  document.getElementById('intg-g-connect')?.addEventListener('click', connectGoogle);
  document.getElementById('intg-g-sync')?.addEventListener('click', syncGoogle);
  document.getElementById('intg-g-disconnect')?.addEventListener('click', disconnectGoogle);
  document.getElementById('intg-g-accounts')?.addEventListener('click', openPicker);
  document.getElementById('intg-c-connect')?.addEventListener('click', connectCalendly);
  document.getElementById('intg-c-disconnect')?.addEventListener('click', disconnectCalendly);
  document.getElementById('intg-r-connect')?.addEventListener('click', openCallrailSetup);
  document.getElementById('intg-r-sync')?.addEventListener('click', syncCallrail);
  document.getElementById('intg-r-disconnect')?.addEventListener('click', disconnectCallrail);

  if (state.autoOpenPicker) {
    state.autoOpenPicker = false;
    if (document.getElementById('intg-g-accounts')) openPicker();
  }
}

// ── account picker: choose which accounts feed reporting ─────────────────────
async function openPicker() {
  const panel = document.getElementById('intg-g-picker');
  if (!panel) return;
  panel.style.display = '';
  panel.innerHTML = alertHTML('Loading your ad accounts…');
  try {
    const res = await fetch(`${apiBase()}/m5t/v5/integrations/google_ads/accounts`);
    const data = await res.json();
    if (!data.ok) throw new Error(data.error || 'load failed');
    renderPicker(data.data.accounts || [], new Set(data.data.linked || []));
  } catch (e) {
    panel.innerHTML = alertHTML('Could not load your ad accounts. Try again, or reconnect if this keeps happening.', 'error');
  }
}

function renderPicker(accounts, linked) {
  const panel = document.getElementById('intg-g-picker');
  if (!panel) return;

  const rows = accounts.map((a) => {
    const disabled = a.manager || a.error;
    const badge = a.manager ? 'Manager' : a.error ? 'Unavailable' : (a.currency || '');
    const checked = linked.has(a.id) && !disabled;
    return `
      <label class="intg-acct${disabled ? ' disabled' : ''}">
        <input type="checkbox" data-intg-acct="${esc(a.id)}" ${checked ? 'checked' : ''} ${disabled ? 'disabled' : ''}>
        <span style="min-width:0">
          <span class="intg-acct__name">${esc(a.name || 'Account ' + a.id)}</span>
          <div class="intg-acct__id">${esc(a.id)}</div>
        </span>
        ${badge ? `<span class="intg-acct__badge">${esc(badge)}</span>` : '<span></span>'}
      </label>`;
  }).join('');

  panel.innerHTML = `
    <div class="intg-picker">
      <div class="intg-picker__head">
        <span>Accounts that feed reporting</span>
        <span style="font-weight:500">${accounts.filter((a) => !a.manager && !a.error).length} selectable</span>
      </div>
      <div class="intg-picker__list">
        ${rows || `<div class="intg-picker__empty">No ad accounts are reachable from this Google account.</div>`}
      </div>
      <div class="intg-picker__foot">
        <button type="button" class="intg-btn" id="intg-picker-cancel">Cancel</button>
        <button type="button" class="intg-btn primary" id="intg-picker-save"><span class="material-symbols-outlined" aria-hidden="true">save</span>Save</button>
      </div>
    </div>`;

  document.getElementById('intg-picker-cancel')?.addEventListener('click', () => { panel.style.display = 'none'; });
  document.getElementById('intg-picker-save')?.addEventListener('click', savePicker);
}

async function savePicker() {
  const panel = document.getElementById('intg-g-picker');
  const ids = [...(panel?.querySelectorAll('input[data-intg-acct]:checked') || [])].map((el) => el.dataset.intgAcct);
  const btn = document.getElementById('intg-picker-save');
  if (btn) btn.disabled = true;
  try {
    const res = await fetch(`${apiBase()}/m5t/v5/integrations/google_ads/accounts`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ customer_ids: ids }),
    });
    const data = await res.json();
    if (!data.ok) throw new Error(data.error || 'save failed');
    toast(`${data.data.linked} account${data.data.linked === 1 ? '' : 's'} linked. First sync is running.`, 'success');
    if (panel) panel.style.display = 'none';
    load();
  } catch (e) {
    toast('Could not save account selection.', 'error');
    if (btn) btn.disabled = false;
  }
}

